user = {"name": "Ada", "role": "admin"}

# Indexing a missing key raises:
try:
    print(user["email"])
except KeyError as e:
    print("missing key:", e)     # missing key: 'email'

# Safe reads with .get:
print(user.get("email"))         # None
print(user.get("email", "n/a"))  # n/a
print("email" in user)           # False  (membership tests keys)

# Accumulating with setdefault:
groups = {}
for name, team in [("a", "x"), ("b", "x"), ("c", "y")]:
    groups.setdefault(team, []).append(name)
print(groups)                    # {'x': ['a', 'b'], 'y': ['c']}
```

