# Squares of even numbers 0..9
result = [x * x for x in range(10) if x % 2 == 0]
print(result)            # [0, 4, 16, 36, 64]

# Equivalent explicit loop (more verbose):
result2 = []
for x in range(10):
    if x % 2 == 0:
        result2.append(x * x)
print(result == result2) # True

# Dict and set comprehensions share the syntax:
squares = {x: x * x for x in range(4)}
print(squares)           # {0: 0, 1: 1, 2: 4, 3: 9}
lengths = {len(w) for w in ["a", "bb", "cc"]}
print(lengths)           # {1, 2}
```

py-flow-003.example:
```python
def find_prime_factor(n):
    for d in range(2, n):
        if n % d == 0:
            print(f"{d} divides {n}")
            break
    else:
        # runs only if no break happened -> no divisor found
        print(f"{n} is prime")

find_prime_factor(15)   # 3 divides 15
find_prime_factor(13)   # 13 is prime

# A loop that never breaks always runs its else:
for x in []:
    pass
else:
    print("else runs even for an empty loop")  # printed
```

py-oop-003.example:
```python
class Animal:
    def __init__(self, name):
        self.name = name
    def describe(self):
        return f"{self.name} is an animal"

class Dog(Animal):
    def __init__(self, name, breed):
        super().__init__(name)     # run Animal.__init__
        self.breed = breed
    def describe(self):
        base = super().describe()  # extend, don't replace
        return f"{base} ({self.breed})"

d = Dog("Rex", "corgi")
print(d.describe())   # Rex is an animal (corgi)

# Inspect the method resolution order:
print([c.__name__ for c in Dog.__mro__])  # ['Dog', 'Animal', 'object']
```

py-oop-006.example:
```python
class Circle:
    def __init__(self, radius):
        self._radius = radius

    @property
    def radius(self):
        return self._radius

    @radius.setter
    def radius(self, value):
        if value < 0:
            raise ValueError("radius must be >= 0")
        self._radius = value

    @property
    def area(self):                 # computed, read-only
        return 3.14159 * self._radius ** 2

c = Circle(2)
print(c.area)        # 12.56636  (no parentheses!)
c.radius = 3         # goes through the setter (validates)
print(c.area)        # 28.27431
try:
    c.area = 100     # no setter -> read-only
except AttributeError as e:
    print("read-only:", e)
```

py-oop-007.example:
```python
class Date:
    def __init__(self, year, month, day):
        self.year, self.month, self.day = year, month, day

    @classmethod
    def from_string(cls, s):          # alternative constructor
        y, m, d = map(int, s.split("-"))
        return cls(y, m, d)           # cls -> works for subclasses too

    @staticmethod
    def is_leap(year):                # pure helper, no self/cls
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

d = Date.from_string("2024-02-29")
print(d.year, d.month, d.day)         # 2024 2 29
print(Date.is_leap(2024))             # True
print(Date.is_leap(2023))             # False
```

py-exc-002.example:
```python
class InsufficientFunds(Exception):
    """Raised when a withdrawal exceeds the balance."""

def withdraw(balance, amount):
    if amount <= 0:
        raise ValueError("amount must be positive")
    if amount > balance:
        raise InsufficientFunds(f"need {amount}, have {balance}")
    return balance - amount

try:
    withdraw(100, 150)
except InsufficientFunds as e:
    print("declined:", e)     # declined: need 150, have 100

try:
    withdraw(100, -5)
except ValueError as e:
    print("invalid:", e)      # invalid: amount must be positive
```

py-exc-003.example:
```python
config = {"timeout": 30}

# EAFP (idiomatic): try, then handle failure
try:
    timeout = config["timeout"]
except KeyError:
    timeout = 10
print(timeout)            # 30

# LBYL: check first (fine here, but redundant work)
if "retries" in config:
    retries = config["retries"]
else:
    retries = 3
print(retries)            # 3

# EAFP shines where a check would race (file may vanish after the check):
try:
    with open("maybe.txt") as f:
        data = f.read()
except FileNotFoundError:
    data = ""
print(repr(data))         # ''
```

py-modern-004.example:
```python
def total(prices: list[float], tax: float = 0.0) -> float:
    return sum(prices) * (1 + tax)

print(total([10.0, 20.0], tax=0.1))   # 33.0

from typing import Optional

def find_user(uid: int) -> Optional[str]:   # str | None
    users = {1: "Ada"}
    return users.get(uid)

print(find_user(1))    # Ada
print(find_user(99))   # None

# Hints are NOT enforced at runtime — this still runs:
print(total([1, 2, 3]))   # 6  (ints work; mypy would flag the type)
print(total.__annotations__)  # {'prices': list[float], 'tax': <class 'float'>, 'return': <class 'float'>}
```
